use vstd::prelude::*;

verus! {

spec fn tril_val(i: int, j: int, k: int) -> bool {
    j <= i + k
}

fn tri(n: usize, m: usize, k: i32) -> Vec<Vec<f64>>
    requires true
    ensures
        tri.len() == n &&
        forall(|i: int| 0 <= i && i < n as int ==>
            tri[i as usize].len() == m &&
            forall(|j: int| 0 <= j && j < m as int ==>
                tril_val(i, j, k as int) ==> tri[i as usize][j as usize] == 1.0 &&
                !tril_val(i, j, k as int) ==> tri[i as usize][j as usize] == 0.0
            )
        )
{
    let mut tri = Vec::with_capacity(n);
    let k_int = k as int;

    let mut i: usize = 0;
    while i < n
        invariant i <= n,
        decreases n - i,
    {
        let mut row = Vec::with_capacity(m);

        let i_int = i as int;
        let mut j: usize = 0;
        while j < m
            invariant j <= m,
            decreases m - j,
        {
            let j_int = j as int;
            if j_int <= i_int + k_int {
                row.push(1.0);
            } else {
                row.push(0.0);
            }
            j += 1;
        }

        tri.push(row);
        i += 1;
    }

    tri
}

}
